pre.code:
.teams-container { display:flex; flex-direction:row; height:100vh; overflow:hidden;
background: rgb(242,242,242); box-sizing:border-box; }
._grid_ { display:grid; grid-template-columns: 264px 1fr; height:100%; width:100%; }
/* 左列 = 侧栏 264px 固定；右列 = 主区 flex 1（1681 视口下算得 1417px） */
._gridViewItem_:nth-child(1) { width:264px; background: rgb(242,242,242); overflow:hidden; }
._gridViewItem_:nth-child(2) { flex:1; background: rgb(250,250,250); overflow:hidden; }

::-webkit-scrollbar { width:10px; height:10px; }
::-webkit-scrollbar-thumb { background: var(--cb-scrollbar-thumb); border-radius:5px; }
::-webkit-scrollbar-thumb:hover { background: var(--cb-scrollbar-thumb-hover); }
::-webkit-scrollbar-track { background: transparent; }
